39	(* ----- M5.3 Free-endpoint lemma --------------------------------------------- *)
40	
41	Lemma endpoint_implies_next_has_left_child :
42	  forall (k : nat) (w : seq nat),
43	    uniq w -> k.+1 < size w -> ~~ is_internal k w ->
44	    has_left_child k.+1 w.
45	Proof.
46	move=> k w; move: w k.
47	suff Hind : forall n k w, size w <= n ->
48	  uniq w -> k.+1 < size w -> ~~ is_internal k w ->
49	  has_left_child k.+1 w by move=> k w; apply: Hind.
50	elim => [|n IH]; first by move=> k [].
51	move=> k [//|a s0] Hsz Huniq Hk1 Hep.
52	set j := mm_pos (a :: s0).
53	have Hj : j < (size s0).+1 by apply: mm_pos_lt.
54	have Hk_lt : k < (size s0).+1 :=
55	  ltn_trans (ltnSn k) Hk1.
56	have Hws_k : window_size k (a :: s0) <= 1.
57	  move: Hep; rewrite /is_internal Hk_lt /=.
58	  by rewrite -leqNgt.
59	case: (ltngtP k j) => [Hkj | Hjk | Hkj].
60	- (* k < j *)
61	  case: (ltngtP k.+1 j) => [Hk1j | Hk1j | Hk1j].
62	  + abstract (
63	    rewrite (has_left_child_cons k.+1 a s0) /= -/j
64	      Hk1j;
65	    apply: IH;
66	    [ rewrite size_take Hj -ltnS;
67	      exact: leq_trans Hj Hsz
68	    | have : uniq (take j (a :: s0) ++
69	               drop j (a :: s0))
70	        by rewrite cat_take_drop;
71	      by rewrite cat_uniq => /andP [? _]
72	    | by rewrite size_take Hj
73	    | rewrite /is_internal size_take Hj Hkj /=;
74	      rewrite -leqNgt;
75	      have H := window_size_cons k a s0;
76	      rewrite /= -/j Hkj in H;
77	      by rewrite -H ]).
78	  + abstract
79	      (by rewrite ltnS in Hk1j;
80	       move: (leq_gtF Hk1j); rewrite Hkj).
81	  + abstract
82	      (rewrite (has_left_child_cons k.+1 a s0) /= -/j;
83	      by rewrite Hk1j ltnn eqxx -Hk1j).
84	- (* j < k *)
85	  abstract (
86	  have Hjk1 : j < k.+1 := ltn_trans Hjk (ltnSn k);
87	  rewrite (has_left_child_cons k.+1 a s0) /= -/j;
88	  have -> : k.+1 < j = false
89	    by apply/negbTE; rewrite -leqNgt ltnW;
90	  have -> : (k.+1 == j) = false by apply: gtn_eqF;
91	  have Hk1_shift : k.+1 - j - 1 = (k - j - 1).+1
92	    by rewrite -!addn1 -!addnBAC ?(ltnW Hjk);
93	  rewrite Hk1_shift;
94	  apply: IH;
95	  [ rewrite size_drop /= -ltnS;
96	    exact: leq_ltn_trans (leq_subr _ _) Hsz
97	  | move: Huniq;
98	    rewrite -{1}(cat_take_drop j.+1 (a :: s0))
99	      cat_uniq;
100	    by move=> /andP [_ /andP [_ ->]]
101	  | rewrite size_drop -Hk1_shift;
102	    exact: ltn_sub2r (ltnW Hjk1) Hk1
103	  | have Hk_dw : k - j - 1 <
104	      size (drop j.+1 (a :: s0))
105	      by apply: ltn_trans (ltnSn _);
106	      rewrite size_drop -Hk1_shift;
107	      exact: ltn_sub2r (ltnW Hjk1) Hk1;
108	    rewrite /is_internal Hk_dw /=;
109	    rewrite -leqNgt;
110	    have H := window_size_cons k a s0;
111	    rewrite /= -/j (ltn_eqF Hjk) in H;
112	    rewrite ifN in H;
113	      last by rewrite -leqNgt ltnW;
114	    by rewrite -H ]).
115	- (* k = j: impossible *)
116	  abstract (
117	  exfalso;
118	  have Hws_root := window_size_cons j a s0;
119	  rewrite /= -/j ltnn eqxx in Hws_root;
120	  have : 1 < (size s0).+1 - j
121	    by rewrite -Hkj ltn_subRL addnC /=;
122	       rewrite Hkj;
123	  by rewrite -Hws_root =>
124	     /(leq_ltn_trans Hws_k); rewrite ltnn).
125	Qed.
