135	(* ----- M5.4 Disjointness of affected position sets ------------------------ *)
136	
137	Lemma window_size_last_fuel :
138	  forall fuel w, size w <= fuel -> 0 < size w ->
139	  window_size_fuel fuel (size w).-1 w = 1.
140	Proof.
141	elim=> [w Hsz Hne|fuel IH [|a s0] Hsz Hne] //.
142	  by move: Hsz Hne; case: w.
143	set s := a :: s0. set j := mm_pos s.
144	have Hj : j < size s by apply: mm_pos_lt.
145	have Hj2 : j <= size s0 by rewrite -ltnS.
146	rewrite /= -/s -/j.
147	have Hjn : (size s0 < j) = false
148	  by apply/negbTE; rewrite -leqNgt.
149	rewrite Hjn.
150	case Hjq: (size s0 == j).
151	  abstract (by move/eqP: Hjq => <-;
152	     rewrite /s /= subSn // subnn).
153	abstract (
154	have Hjl : j < size s0
155	  by rewrite ltn_neqAle eq_sym Hjq /=
156	     leqNgt Hjn;
157	change (window_size_fuel fuel
158	  (size s0 - j - 1) (drop j s0) = 1);
159	have Hsz_ds : size (drop j s0) = size s0 - j
160	  by rewrite size_drop;
161	have H0ds : 0 < size (drop j s0)
162	  by rewrite Hsz_ds subn_gt0;
163	have Hfuel_ok : size (drop j s0) <= fuel
164	  by rewrite Hsz_ds;
165	  apply: leq_trans (leq_subr _ _) _;
166	  rewrite ltnS in Hsz;
167	have -> : size s0 - j - 1 =
168	  (size (drop j s0)).-1
169	  by rewrite Hsz_ds subn1;
170	exact: IH Hfuel_ok H0ds).
171	Qed.
172	
173	Lemma window_size_last w :
174	  0 < size w ->
175	  window_size (size w).-1 w = 1.
176	Proof.
177	move=> Hne; rewrite /window_size.
178	exact: window_size_last_fuel (leqnn _) Hne.
179	Qed.
