181	Lemma LR_pred_is_endpoint :
182	  forall (i : nat) (w : seq nat),
183	  uniq w -> 0 < i -> is_internal i w ->
184	  has_left_child i w ->
185	  ~~ is_internal i.-1 w.
186	Proof.
187	suff H : forall n i w, size w <= n ->
188	  uniq w -> 0 < i -> is_internal i w ->
189	  has_left_child i w ->
190	  ~~ is_internal i.-1 w.
191	  by move=> i w; exact: H (leqnn _).
192	elim=> [i w Hsz _ _ Hint _|
193	  n IH i [|a s0] Hsz Huniq Hi0 Hint Hlc] //.
194	  move: Hint; rewrite /is_internal =>
195	    /andP [Hi _].
196	  by move: (leq_trans Hi Hsz); rewrite ltn0.
197	set s := a :: s0. set j := mm_pos s.
198	have Hj : j < size s by apply: mm_pos_lt.
199	have Hj2 : j <= size s0 by rewrite -ltnS.
200	have Hiw : i < size s
201	  by move: Hint; rewrite /is_internal =>
202	     /andP [].
203	have Hws : 1 < window_size i s
204	  by move: Hint; rewrite /is_internal =>
205	     /andP [].
206	rewrite has_left_child_cons -/s -/j in Hlc.
207	rewrite window_size_cons -/s -/j in Hws.
208	case: (ltngtP i j) => [Hij | Hji | Heq].
209	- (* i < j: both i and i-1 in left subtree *)
210	  abstract (
211	  rewrite Hij in Hlc Hws;
212	  have Hi1j : i.-1 < j
213	    by exact:
214	       leq_ltn_trans (leq_pred _) Hij;
215	  rewrite /is_internal window_size_cons
216	    -/s -/j Hi1j;
217	  have Htake_sz : size (take j s) = j
218	    by rewrite size_take Hj;
219	  have Huniq_t : uniq (take j s)
220	    by exact:
221	       subseq_uniq (take_subseq _ _) Huniq;
222	  case E:
223	    (1 < window_size i.-1 (take j s));
224	    last by rewrite andbF;
225	  have Hint_t : is_internal i (take j s)
226	    by rewrite /is_internal Htake_sz Hij Hws;
227	  have Hsz_t : size (take j s) <= n
228	    by rewrite Htake_sz;
229	    apply: leq_trans Hj2 _;
230	    rewrite /s /= ltnS in Hsz;
231	  have := IH i (take j s) Hsz_t Huniq_t
232	    Hi0 Hint_t Hlc;
233	  by rewrite /is_internal
234	     Htake_sz Hi1j /= E).
235	- (* j < i: right subtree *)
236	  abstract (
237	  have Hlti : ~~ (i < j)
238	    by rewrite -leqNgt ltnW;
239	  have Hi_ne_j : (i == j) = false
240	    by rewrite gtn_eqF;
241	  rewrite (negbTE Hlti) Hi_ne_j in Hlc Hws;
242	  case Ei1j : (i.-1 == j);
243	  [ move/eqP: Ei1j => Ei1j;
244	    have Ei : i = j.+1
245	      by rewrite -(prednK Hi0) Ei1j;
246	    by rewrite Ei subSn // subnn
247	       has_left_child_0 in Hlc
248	  | have Hi1j : j < i.-1
249	      by rewrite ltn_neqAle eq_sym Ei1j /=;
250	      rewrite -ltnS (prednK Hi0);
251	    have Huniq_d : uniq (drop j.+1 s)
252	      by exact:
253	         subseq_uniq (drop_subseq _ _) Huniq;
254	    have Hi0' : 0 < i - j - 1
255	      by rewrite ltn_predRL in Hi1j;
256	      rewrite -subnDA addn1 subn_gt0;
257	    have Hpred :
258	      (i - j - 1).-1 = i.-1 - j - 1
259	      by rewrite !predn_sub;
260	    have Hsz_d : size (drop j.+1 s) <= n
261	      by rewrite /s /= size_drop;
262	      apply: leq_trans (leq_subr _ _) _;
263	      rewrite /s /= ltnS in Hsz;
264	    have Hi_ds :
265	      i - j - 1 < size (drop j.+1 s)
266	      by rewrite /s /= size_drop;
267	      have Hisz : i <= size s0
268	        by rewrite -ltnS;
269	      have H3 : 0 < i - j
270	        by rewrite subn_gt0;
271	      have H4 : i - j <= size s0 - j :=
272	        leq_sub2r j Hisz;
273	      have H5 : i - j - 1 < i - j
274	        by case: (i - j) H3 => [//|k _] /=;
275	        rewrite subSS; exact: leq_subr;
276	      exact: leq_trans H5 H4;
277	    have Hint_d :
278	      is_internal (i - j - 1) (drop j.+1 s)
279	      by rewrite /is_internal Hi_ds Hws;
280	    have Hih :=
281	      IH _ _ Hsz_d Huniq_d Hi0' Hint_d Hlc;
282	    move: Hih; rewrite /is_internal Hpred;
283	    set ds := drop j.+1 s;
284	    rewrite negb_and => /orP [Hoor | Hws1];
285	    [ rewrite /is_internal window_size_cons
286	        -/s -/j;
287	      have Hi1ltj : (i.-1 < j) = false
288	        by rewrite ltnNge ltnW;
289	      rewrite Hi1ltj Ei1j -/ds;
290	      rewrite negb_and; apply/orP; right;
291	      move: Hoor; rewrite -leqNgt => Hoor;
292	      by rewrite -leqNgt
293	         (window_size_oor Hoor)
294	    | rewrite /is_internal window_size_cons
295	        -/s -/j;
296	      have Hi1ltj : (i.-1 < j) = false
297	        by rewrite ltnNge ltnW;
298	      rewrite Hi1ltj Ei1j -/ds;
299	      by rewrite negb_and -leqNgt
300	         (negbTE Hws1) orbT ] ]).
301	- (* i = j: root, i-1 last of left subtree *)
302	  abstract (
303	  rewrite -Heq eqxx in Hlc Hws;
304	  have Hj0 : 0 < j by rewrite -Heq;
305	  rewrite /is_internal window_size_cons
306	    -/s -/j;
307	  rewrite Heq ltn_predL Hj0;
308	  have Htake_sz : size (take j s) = j
309	    by rewrite size_take Hj;
310	  rewrite negb_and; apply/orP; right;
311	  rewrite -leqNgt;
312	  have -> : j.-1 = (size (take j s)).-1
313	    by rewrite Htake_sz;
314	  have H0t : 0 < size (take j s)
315	    by rewrite Htake_sz;
316	  by rewrite (window_size_last H0t)).
317	Qed.
